/// `#[derive(lr::Trace)] #[dumpster(crate = lr::gc::dumpster)]` in generated code.
pub use dumpster::Trace;
pub use dynamic::Value;
pub use error::{at, LResult, LuaError};
pub use handle::{Handle, HandleMeta};
pub use show::{LuaDisplay, LuaType};
pub use table::Table;
pub use value::{narrowed, present, Arr, Callable, Cell, FalseOr, LFn, LMap, LStr, MetaRec, NumKey, PcallVal, Rec};

/// Entry point used by generated `main` functions: runs the program, flushes
/// stdout, reports an uncaught language error on stderr and exits non-zero.
pub fn run_main(body: impl FnOnce() -> LResult<()>) {
    gc::initialize();
    callback::install_panic_hook();
    // tasks still pending when the entry module finishes run to completion
    // (their errors are uncaught errors of the program)
    // backstop: a callback error unwinding outside any guarded native call (e.g. a
    // native destructor running a retained callback) is still reported
    let result = callback::guard(|| body().and_then(|()| task::wait_idle())).and_then(|r| r);
    finish_main(Some(result));
}

/// Coroutine programs run the entry chunk on a real root stack, as Luau CLI
/// does. A yield reaches this host boundary without becoming a catchable error.
pub fn run_main_coroutine(body: impl FnOnce() -> LResult<()> + 'static) {
    gc::initialize();
    callback::install_panic_hook();
    let result = coroutine::drive_entry(move || callback::guard(|| body().and_then(|()| task::wait_idle())).and_then(|r| r));
    finish_main(match result {
        coroutine::Entry::Returned(result) => Some(result),
        coroutine::Entry::Yielded => None,
    });
}

fn finish_main(result: Option<LResult<()>>) -> ! {
    task::cancel_all();
    let code = match result {
        Some(Ok(())) => 0,
        Some(Err(e)) => {
            stdlib::flush_stdout();
            eprintln!("luarc runtime error: {}", e.msg.to_string_lossy());
            1
        }
        None => {
            stdlib::flush_stdout();
            eprintln!("thread yielded unexpectedly");
            1
        }
    };
    shutdown::release_all();
    stdlib::flush_stdout();
    std::process::exit(code);
}

/// Command-line arguments passed after `--` (the program name excluded).
pub fn program_args() -> Arr<LStr> {
    Arr::from_vec(std::env::args_os().skip(1).map(|a| LStr::from(a.to_string_lossy().as_ref())).collect())
}


